"""Brute-force solvers for ThreeSat and Clique, from the definitions."""
from itertools import product


def sat_solve(inst):
    m = inst["num_vars"]
    clauses = inst["clauses"]
    for bits in product([False, True], repeat=m):
        ok = True
        for cl in clauses:
            if not any((bits[abs(l) - 1] if l > 0 else not bits[abs(l) - 1]) for l in cl):
                ok = False
                break
        if ok:
            return True
    return False


def clique_solve(inst):
    """True iff graph has a clique of size >= k (exact branch & bound)."""
    n = inst["n"]
    k = inst["k"]
    if k <= 0:
        return True
    if k > n:
        return False
    adj = [0] * n
    for u, v in inst["edges"]:
        adj[u] |= 1 << v
        adj[v] |= 1 << u

    # Find maximum clique size via simple recursive search.
    best = 0

    def expand(cand, size):
        nonlocal best
        if size + bin(cand).count("1") <= best:
            return
        if cand == 0:
            if size > best:
                best = size
            return
        while cand:
            if size + bin(cand).count("1") <= best:
                return
            v = (cand & -cand).bit_length() - 1
            cand &= ~(1 << v)
            expand(cand & adj[v], size + 1)
            if best >= k:
                return

    expand((1 << n) - 1, 0)
    return best >= k
EOF
